  .cat-grid { grid-template-columns: repeat(3, minmax(0, 1fr)); }
  .cat-grid .cat-card:nth-child(4), .cat-grid .cat-card:nth-child(5) { grid-column: span 1; }
  .benefit-grid { grid-template-columns: repeat(3, minmax(0, 1fr)); }
  .steps-5 { grid-template-columns: repeat(3, minmax(0, 1fr)); row-gap: 40px; }
  .steps-5 .step:nth-child(3)::after { display: none; }
  .combo { grid-template-columns: minmax(0, 1fr) auto minmax(0, 1fr); }
  .combo-eq { display: none; }
  .combo-result { grid-column: 1 / -1; }
}

@container site (max-width: 1100px) {
  .shell { --section: 72px; --h-display: 38px; --h1: 34px; --h2: 28px; }
  .product-grid-4 { grid-template-columns: repeat(3, minmax(0, 1fr)); }
  .product-grid-4 > .pcard:nth-child(4) { display: none; }
  .product-grid-3 { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .utility .hide-md { display: none; }
  .logo-tag { display: none; }
  .reviews-layout { grid-template-columns: 280px minmax(0, 1fr); gap: 32px; }
  .review-grid { grid-template-columns: minmax(0, 1fr); }
  .review-grid > .review:nth-child(n+3) { display: none; }
  .topic-grid { grid-template-columns: repeat(3, minmax(0, 1fr)); }
  .principle-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .cart-layout { grid-template-columns: minmax(0, 1fr) 340px; gap: 32px; }
  .checkout-layout { grid-template-columns: minmax(0, 1fr) 340px; gap: 32px; }
  .dash-showcase .dash { font-size: 13px; }
}

@container site (max-width: 960px) {
  .shell { --gutter: 28px; --section: 64px; }
  /* header → hamburger */
  .burger { display: inline-grid; margin-left: -8px; }
  .nav, .header-account { display: none; }
  .header-bar { height: 68px; gap: 12px; }
  .logo-mark { width: 38px; height: 38px; }
  .logo-name { font-size: 19px; }
  .header-actions { margin-left: auto; }
  .mobile-nav { max-height: calc(100vh - 68px); overflow-y: auto; }
  .filters, .gallery, .summary, .faq-side { top: 84px; }
  /* layouts stack */
  .hero { padding: 40px 0 56px; }
  .hero-grid, .split, .about-split, .contact-layout, .faq-teaser { grid-template-columns: minmax(0, 1fr); gap: 40px; }
  .hero-visual { max-width: 560px; width: 100%; }
  .hero-online .hero-visual { max-width: 620px; }
  .reviews-layout { grid-template-columns: minmax(0, 1fr); }
  .review-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .review-grid > .review:nth-child(n+3) { display: flex; }
  .steps-4 { grid-template-columns: repeat(2, minmax(0, 1fr)); row-gap: 36px; }
  .steps-4 .step:nth-child(2)::after { display: none; }
  .feature-grid, .guide-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .guide-grid .guide-card-featured { grid-column: 1 / -1; }
  .plan-grid { grid-template-columns: minmax(0, 1fr); max-width: 560px; }
  .plan-featured { order: -1; }
  .callouts { grid-template-columns: minmax(0, 1fr); }
  .footer-top { grid-template-columns: repeat(3, minmax(0, 1fr)); }
  .footer-brand { grid-column: 1 / -1; }
  .footer-mid { grid-template-columns: minmax(0, 1fr); align-items: start; gap: 28px; }
  .footer-trust { justify-content: flex-start; }
  .footer-bottom { flex-direction: column; }
  .footer-bottom p:last-child { text-align: left; }
  .cta-band { grid-template-columns: minmax(0, 1fr); padding: 40px; }
  /* shop → drawer */
  .shop { grid-template-columns: minmax(0, 1fr); }
  .filters { display: none; position: absolute; inset: 0 auto auto 0; z-index: 30; width: 100%; min-height: 100%; padding: 20px var(--gutter) 32px; margin-inline: calc(-1 * var(--gutter)); width: calc(100% + 2 * var(--gutter)); background: #fff; box-shadow: 0 0 0 1px var(--border); }
  .filters.is-open { display: flex; }
  .filters-close, .filters-apply { display: inline-flex; }
  .filters-open { display: inline-flex; }
  .filters .help-card { display: none; }
  .filters-foot { grid-template-columns: 1fr 1fr; position: sticky; bottom: 0; background: #fff; padding-bottom: 12px; }
  .filters .btn { height: 48px; }
  .search { max-width: none; }
  /* pdp */
  .pdp-grid { grid-template-columns: minmax(0, 1fr); gap: 32px; }
  .gallery { position: static; }
  .benefit-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .tab-split { grid-template-columns: minmax(0, 1fr); gap: 32px; }
  .toc { grid-template-columns: minmax(0, 1fr); }
  .sticky-bar { position: sticky; bottom: 0; z-index: 40; display: flex; align-items: center; justify-content: space-between; gap: 16px; padding: 12px var(--gutter); background: #fff; border-top: 1px solid var(--border); box-shadow: 0 -12px 24px -18px rgba(11, 37, 69, .35); }
  .sticky-bar-info { display: flex; flex-direction: column; min-width: 0; line-height: 1.3; }
  .sticky-bar-info .t-cap { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  .cart-section .sticky-bar { margin-inline: calc(-1 * var(--gutter)); margin-top: 32px; }
  /* cart & checkout */
  .cart-layout, .checkout-layout { grid-template-columns: minmax(0, 1fr); }
  .summary { position: static; }
  .summary-checkout { display: none; }
  .mobile-summary { display: block; margin-bottom: 20px; border: 1px solid var(--border); border-radius: var(--r-lg); background: var(--page); }
  .mobile-summary summary { display: flex; align-items: center; gap: 10px; min-height: 56px; padding: 0 16px; font-weight: 600; cursor: pointer; list-style: none; }
  .mobile-summary summary::-webkit-details-marker { display: none; }
  .mobile-summary summary > span { display: inline-flex; align-items: center; gap: 8px; }
  .mobile-summary summary strong { margin-left: auto; }
  .mini-lines { display: grid; gap: 10px; padding: 0 16px 16px; font-size: 14px; }
  .mini-lines li { display: grid; grid-template-columns: 32px minmax(0, 1fr) auto; gap: 8px; }
  .mini-qty { font-weight: 700; }
  .faq-layout { grid-template-columns: minmax(0, 1fr); gap: 24px; }
  .faq-side { position: static; }
  .faq-cats { display: flex; gap: 8px; overflow-x: auto; padding-bottom: 4px; scrollbar-width: none; }
  .faq-cats::-webkit-scrollbar { display: none; }
  .faq-cat { width: auto; white-space: nowrap; border: 1.5px solid var(--border); }
  .faq-cat.is-active { border-color: var(--navy); }
  .faq-side .help-card { display: none; }
  .combo { grid-template-columns: minmax(0, 1fr); }
  .combo-plus { justify-self: center; }
  .combo-result { grid-column: auto; }
}

@container site (max-width: 720px) {
  .shell { --gutter: 16px; --section: 56px; --h-display: 31px; --h1: 29px; --h2: 25px; --h3: 20px; }
  .site { font-size: 16px; }
  .lead { font-size: 17px; }
  .utility-bar { height: 36px; justify-content: center; font-size: 13px; }
  .utility-right { display: none; }
  .utility .hide-sm { display: none; }
  .header-bar { height: 64px; }
  .logo-mark { width: 34px; height: 34px; }
  .logo-name { font-size: 17px; }
  .cart-link { padding: 0 10px; height: 44px; }
  .cart-link-label { display: none; }
  .toast-slot { right: var(--gutter); left: var(--gutter); width: auto; }
  .mobile-nav { max-height: calc(100vh - 64px); }
  .filters, .gallery, .summary, .faq-side { top: 80px; }
  .section-head { flex-direction: column; align-items: flex-start; margin-bottom: 28px; }
  .section-head-center { align-items: center; }
  .btn-row > .btn { width: 100%; }
  .hero-copy .btn-row { width: 100%; }
  .hero-trust { flex-direction: column; align-items: flex-start; gap: 10px; }
  .hero-card { padding: 12px; }
  .hero-card-exam { width: 52%; right: 4%; top: 6%; }
  .hero-card-progress { width: 46%; right: 4%; bottom: 6%; }
  .hero-card-topic { left: 4%; bottom: 6%; padding: 10px 12px; }
  .hero-card-topic .hc-text span { display: none; }
  .hc-big { font-size: 22px; }
  .ring { width: 44px; height: 44px; }
  .ring::before { inset: 5px; }
  .ring b { font-size: 13px; }
  .usps { padding-bottom: 8px; }
  .usp-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 10px; }
  .usp { padding: 16px 14px; }
  .cat-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 10px; }
  .cat-card { padding: 16px; gap: 12px; }

